<script>
 import {onMount} from 'svelte';import {listSites,updateSiteDomain,installCloudflared,getCloudflareConfig,saveCloudflareConfig,disconnectCloudflare,listCloudflareDNS,createCloudflareTunnelDNS,deleteCloudflareDNS} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let sites=[],drafts={},tokens={},loading=true,busyKey='';
 let cf={connected:false,zone_id:'',zone_name:''},cfToken='',cfZoneID='',cfHostname='',cfTunnelID='',cfRecords=[],cfBusy=false;
 async function load(){const r=await listSites();if(r.ok){sites=r.data.sites||[];const next={},nextTokens={};for(const item of sites){const k=item.device_id+':'+item.site.site_id;next[k]=item.site.domain||'';nextTokens[k]=''}drafts=next;tokens=nextTokens}else notify(r.error||'Не удалось загрузить сайты','error');loading=false}
 onMount(async()=>{await Promise.all([load(),loadCloudflare()])});
 async function loadCloudflare(){const r=await getCloudflareConfig();if(r.ok){cf={...cf,...r.data};cfZoneID=cf.zone_id||'';if(cf.connected)await loadDNS()}else notify(r.error||'Не удалось загрузить Cloudflare','error')}
 async function loadDNS(){const r=await listCloudflareDNS();if(r.ok)cfRecords=r.data.records||[];else notify(r.error||'Не удалось загрузить DNS','error')}
 async function connectCloudflare(){if(cfBusy)return;cfBusy=true;const r=await saveCloudflareConfig(cfToken,cfZoneID);cfBusy=false;if(!r.ok){notify(r.error||'Не удалось подключить Cloudflare','error');return}cfToken='';cf={connected:true,zone_id:r.data.zone_id,zone_name:r.data.zone_name};notify('Cloudflare zone подключена','success');await loadDNS()}
 async function removeCloudflare(){if(!confirm('Отключить Cloudflare DNS API?'))return;cfBusy=true;const r=await disconnectCloudflare();cfBusy=false;if(r.ok){cf={connected:false};cfRecords=[];notify('Cloudflare отключён','success')}else notify(r.error||'Не удалось отключить Cloudflare','error')}
 async function createDNS(){if(cfBusy)return;cfBusy=true;const r=await createCloudflareTunnelDNS(cfHostname,cfTunnelID);cfBusy=false;if(!r.ok){notify(r.error||'Не удалось создать DNS запись','error');return}cfHostname='';cfTunnelID='';notify('Cloudflare Tunnel DNS record создан','success');await loadDNS()}
 async function removeDNS(record){if(!confirm('Удалить DNS запись '+record.name+'?'))return;cfBusy=true;const r=await deleteCloudflareDNS(record.id);cfBusy=false;if(r.ok){cfRecords=cfRecords.filter(x=>x.id!==record.id);notify('DNS запись удалена','success')}else notify(r.error||'Не удалось удалить DNS запись','error')}
 async function save(item,key){busyKey=key;const r=await updateSiteDomain(item.device_id,item.site.site_id,drafts[key]||'',tokens[key]||'');busyKey='';tokens[key]='';if(r.ok&&r.data.tunnel_status==='active'){notify('Cloudflare Tunnel подключён · edge-соединение подтверждено','success');await load()}else if(r.ok){notify(r.data.message||'Домен сохранён, но туннель не активен','error');await load()}else notify(r.error||'Не удалось сохранить домен','error')}
 async function installCloudflaredFor(item){busyKey=item.device_id+':'+item.site.site_id;const r=await installCloudflared(item.device_id,item.site.site_id);busyKey='';if(r.ok){notify('cloudflared установлен','success');await load()}else notify(r.error||'Не удалось установить cloudflared','error')}
 async function removeDomain(item,key){busyKey=key;const r=await updateSiteDomain(item.device_id,item.site.site_id,'','');busyKey='';if(r.ok){notify('Домен удалён, Cloudflare Tunnel остановлен','success');await load()}else notify(r.error||'Не удалось остановить туннель и удалить домен','error')}
</script>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE</div><h1 class="page-title">Domains</h1><p class="page-desc">Сохранение домена запускает Cloudflare Tunnel на устройстве сайта.</p></div><Button on:click={load}>↻ Обновить</Button></div>
<div class="notice">Для подключения нужен Tunnel token из Cloudflare Zero Trust → Networks → Tunnels. В Public Hostname настройте этот hostname и origin <code>http://localhost:порт-сайта</code>. Статус Tunnel connected подтверждает регистрацию коннектора на Cloudflare Edge; доступность HTTP-origin проверяется отдельно.</div>
<section class="cloudflare-panel">
 <div class="cf-heading"><div><h2>Cloudflare DNS Automation</h2><p>Автоматически создаёт proxied CNAME для Cloudflare Tunnel. API token хранится зашифрованным.</p></div>{#if cf.connected}<span class="cf-connected">● Connected · {cf.zone_name}</span>{/if}</div>
 {#if !cf.connected}
  <div class="cf-config"><input class="input" type="password" bind:value={cfToken} placeholder="Cloudflare API token" autocomplete="new-password"/><input class="input" bind:value={cfZoneID} placeholder="Zone ID"/><Button variant="primary" loading={cfBusy} disabled={!cfToken||!cfZoneID} on:click={connectCloudflare}>Connect zone</Button></div>
  <small class="cf-help">Создайте scoped API token с Zone:Read и DNS:Edit только для нужной зоны.</small>
 {:else}
  <div class="cf-config"><input class="input" bind:value={cfHostname} placeholder="app.example.com"/><input class="input" bind:value={cfTunnelID} placeholder="Cloudflare Tunnel UUID"/><Button variant="primary" loading={cfBusy} disabled={!cfHostname||!cfTunnelID} on:click={createDNS}>Create / Update CNAME</Button><Button variant="ghost" loading={cfBusy} on:click={loadDNS}>Refresh</Button><Button variant="danger" loading={cfBusy} on:click={removeCloudflare}>Disconnect</Button></div>
  {#if cfRecords.length}<div class="cf-records">{#each cfRecords as record}<div class="cf-record"><div><strong>{record.name}</strong><small>{record.type} → {record.content} · {record.proxied?'Proxied':'DNS only'}</small></div><Button size="sm" variant="danger" on:click={()=>removeDNS(record)}>Delete</Button></div>{/each}</div>{:else}<small class="cf-help">DNS записей пока нет.</small>{/if}
 {/if}
</section>
{#if loading}<div class="empty">Загрузка сайтов…</div>{:else if !sites.length}<div class="empty">Сначала создайте сайт на подключённом устройстве.</div>{:else}
<div class="domain-list">{#each sites as item}{@const key=item.device_id+':'+item.site.site_id}{@const status=item.site.tunnel_status||'inactive'}<article class="domain-row"><div class="site"><span class="site-icon">◎</span><span><strong>{item.site.site_id}</strong><small>{item.device_name} · :{item.site.port}</small></span></div><div class="domain-fields"><div class="domain-input"><input class="input" type="text" placeholder="app.example.com" bind:value={drafts[key]}/></div><input class="input token" type="password" autocomplete="off" placeholder={item.site.domain?'Tunnel token (оставьте пустым, чтобы использовать сохранённый)':'Cloudflare Tunnel token · eyJ…'} bind:value={tokens[key]}/><div class="domain-actions"><Button size="sm" variant="primary" loading={busyKey===key} on:click={()=>save(item,key)}>Сохранить и подключить</Button>{#if item.site.domain}<Button size="sm" variant="ghost" disabled={busyKey===key} on:click={()=>removeDomain(item,key)}>Удалить домен</Button>{/if}</div></div><div class="routing"><StatusDot status={status==='active'?'online':'offline'}/><span class:active={status==='active'}>{status==='active'?'Tunnel connected':status==='pending'?'Connecting…':status==='error'?'Tunnel error · '+(item.site.tunnel_error||'ошибка'):'No domain'}</span>{#if status==='error'&&String(item.site.tunnel_error||'').includes('cloudflared')}<Button size="sm" on:click={()=>installCloudflaredFor(item)}>Установить cloudflared</Button>{/if}</div></article>{/each}</div>
{/if}
<style>
.cloudflare-panel{display:grid;gap:10px;padding:15px;background:#101727;border:1px solid #253149;border-radius:11px;margin-bottom:14px}.cf-heading{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.cf-heading h2{font-size:13px;margin:0 0 4px}.cf-heading p,.cf-help{font-size:10px;color:#94a3b8;line-height:1.5;margin:0}.cf-connected{font-size:10px;color:#4ade80;white-space:nowrap}.cf-config{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}.cf-records{display:grid;gap:6px}.cf-record{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px;border:1px solid #253149;border-radius:8px}.cf-record>div{display:grid;gap:3px;min-width:0}.cf-record strong{font-size:10px}.cf-record small{font-size:9px;color:#64748b;overflow-wrap:anywhere}@media(max-width:700px){.cf-config{grid-template-columns:1fr}.cf-heading{flex-direction:column}}

.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.notice{padding:12px 14px;border:1px solid #334155;border-radius:9px;background:#101727;color:#94A3B8;font-size:10px;line-height:1.6;margin-bottom:12px}.notice code{color:#C4B5FD}.domain-list{border:1px solid #253149;border-radius:11px;background:#101727;overflow:hidden}.domain-row{display:grid;grid-template-columns:minmax(140px,.8fr) minmax(260px,1.5fr) minmax(180px,1fr);align-items:center;gap:15px;padding:14px;border-bottom:1px solid #1e293b}.domain-row:last-child{border:0}.site{display:flex;align-items:center;gap:9px;min-width:0}.site-icon{width:30px;height:30px;display:grid;place-items:center;background:#172136;color:#a5b4fc;border-radius:8px}.site span:last-child{display:grid;gap:3px}.site strong{font-size:10px}.site small,.routing{font-size:9px;color:#64748b}.domain-fields{display:flex;flex-direction:column;gap:7px}.domain-actions{display:flex;gap:7px;flex-wrap:wrap}.domain-input{display:flex;gap:7px}.domain-input input,.token{width:100%;min-width:0}.routing{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.routing .active{color:#22C55E;font-weight:650}.token{font-size:10px}
@media(max-width:760px){.domain-row{grid-template-columns:1fr}.routing{padding-left:39px}}
</style>